```javascript
const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

rl.on('line', (input) => {
  const n = parseInt(input);
  const stack = [];
  for (let i = 0; i < n; i++) {
    let current = 1;
    while (stack.length > 0 && stack[stack.length - 1] === current) {
      current = stack.pop() + 1;
    }
    stack.push(current);
  }
  console.log(stack.join(' '));
  rl.close();
});
